const lessons = [
{id:1,title:'自我介绍与工作交流',en:'A little about me',category:'工作',topic:'第一次和海外同事见面',words:[['colleague','/ˈkɑːliːɡ/','同事','I communicate with my colleagues every day.','我每天和同事沟通。'],['responsible','/rɪˈspɑːnsəbl/','负责的',"I am responsible for API testing.",'我负责接口测试。'],['project','/ˈprɑːdʒekt/','项目','I am working on a new project.','我正在做一个新项目。'],['experience','/ɪkˈspɪriəns/','经验','I have experience in software testing.','我有软件测试经验。'],['improve','/ɪmˈpruːv/','提高','I want to improve my English.','我想提高英语。'],['communicate','/kəˈmjuːnɪkeɪt/','沟通','I communicate with the team in English.','我用英语和团队沟通。'],['develop','/dɪˈveləp/','开发','We develop automation tools.','我们开发自动化工具。'],['schedule','/ˈskedʒuːl/','日程','Let me check my schedule.','让我看看日程。'],['feedback','/ˈfiːdbæk/','反馈','Thank you for your feedback.','谢谢你的反馈。'],['opportunity','/ˌɑːpərˈtuːnəti/','机会','This is a good opportunity to learn.','这是一个学习的好机会。']],lines:[['Tom','Hi, nice to meet you. Are you new to the team?','你好，很高兴认识你。你是新加入团队的吗？'],['Sunny','Yes, I joined the team recently. Nice to meet you too.','是的，我最近加入团队。我也很高兴认识你。'],['Tom','What do you do?','你从事什么工作？'],['Sunny',"I’m a QA engineer. I mainly work on testing and automation.",'我是一名测试工程师，主要做测试和自动化。'],['Tom','That’s great. How long have you worked in this field?','太好了。你在这个领域工作多久了？'],['Sunny','I’ve been working in this field for about six years.','我在这个领域工作大约六年了。']],quiz:[['What does Sunny do?',['A software developer','A QA engineer','A project manager'],1],['How long has Sunny worked in this field?',['About two years','About four years','About six years'],2]],prompts:[['Could you introduce yourself and tell me a little about your work?','介绍你自己，并简单说说你的工作。',"Hi, my name is Sunny. I’m a QA engineer. I mainly focus on testing and automation."],['What are you responsible for?','你主要负责什么？','I am responsible for API testing and automation.'],['How much experience do you have?','你有多少工作经验？','I have about six years of experience in software testing.'],['Why are you learning English?','你为什么学英语？','I want to communicate with my colleagues and travel abroad.'],['What are you working on today?','你今天在做什么？','I am working on API testing today.']],phrases:["I'm working on this task.","I've finished the testing.",'I found an issue.',"I'll check it later.",'Could you explain that again?']},
{id:2,title:'点一杯咖啡，开启一天',en:'Coffee, please',category:'日常',topic:'在咖啡店点单',seed:[['order','点单','I would like to order a coffee.'],['medium','中杯的','A medium coffee, please.'],['takeaway','外带','Is this for takeaway?'],['receipt','收据','Could I have a receipt?'],['milk','牛奶','Can I have some milk?'],['sugar','糖','No sugar, please.'],['hot','热的','I would like a hot coffee.'],['cold','冷的','Do you have cold drinks?'],['pay','付款','Can I pay by card?'],['recommend','推荐','What do you recommend?']],lines:[['Barista','Hi! What would you like?','你好！想喝点什么？'],['Sunny','A medium coffee with milk, please.','请给我一杯中杯加奶咖啡。'],['Barista','For here or to go?','在这里喝还是带走？'],['Sunny','To go, please. Can I pay by card?','请打包。我能刷卡吗？'],['Barista','Of course. That’s four dollars.','当然。一共四美元。']],quiz:[['What does Sunny order?',['Tea','Coffee with milk','Water'],1],['How does Sunny want to pay?',['By card','With cash','By check'],0]],prompts:[['What would you like to drink?','你想喝点什么？','I would like a medium coffee with milk, please.'],['For here or to go?','堂食还是外带？','To go, please.'],['Would you like any sugar?','要加糖吗？','No sugar, thank you.'],['How would you like to pay?','你想怎样付款？','Can I pay by card?'],['Is there anything else?','还需要什么吗？','Could I have a receipt, please?']]},
{id:3,title:'站会中同步工作进度',en:'A quick update',category:'工作',topic:'每日站会',seed:[['update','更新进展','Here is a quick update.'],['finish','完成','I finished the testing yesterday.'],['task','任务','I am working on this task.'],['blocker','阻塞问题','There is one blocker.'],['issue','问题','I found an issue.'],['check','检查','Let me check the logs.'],['today','今天','I will test the API today.'],['yesterday','昨天','I fixed it yesterday.'],['help','帮助','I need some help.'],['ready','准备好的','The report is ready.']],lines:[['Manager','Could you give us a quick update?','你可以简短同步一下进展吗？'],['Sunny','I finished the login testing yesterday.','我昨天完成了登录测试。'],['Manager','What are you working on today?','你今天在做什么？'],['Sunny','I am testing the payment API. I found one issue.','我在测试支付接口，发现了一个问题。'],['Manager','Do you need any help?','需要帮助吗？'],['Sunny','Yes. Could you help me check the logs?','是的，你能帮我检查日志吗？']],quiz:[['What did Sunny finish?',['Login testing','A design','A meeting'],0],['What help does Sunny need?',['Writing email','Checking logs','Booking a room'],1]],prompts:[['What did you finish yesterday?','你昨天完成了什么？','I finished the login testing yesterday.'],['What are you working on today?','你今天在做什么？','I am testing the payment API today.'],['Are there any blockers?','有什么阻塞吗？','Yes. I found an issue in the payment API.'],['What help do you need?','你需要什么帮助？','Could you help me check the logs?'],['When will you give us an update?','你什么时候同步进展？','I will give you an update this afternoon.']]},
{id:4,title:'问路与乘坐地铁',en:'Finding my way',category:'出国',topic:'向路人询问车站位置',seed:[['station','车站','Where is the nearest station?'],['ticket','票','I need a single ticket.'],['left','左边','Turn left here.'],['right','右边','Turn right at the corner.'],['straight','直走','Go straight ahead.'],['near','附近','Is it near here?'],['walk','步行','It is a short walk.'],['map','地图','Could you show me on the map?'],['exit','出口','Take exit two.'],['line','线路','Which line should I take?']],lines:[['Sunny','Excuse me, where is the nearest subway station?','打扰一下，最近的地铁站在哪里？'],['Local','Go straight and turn left at the corner.','直走，在拐角左转。'],['Sunny','Is it far from here?','离这里远吗？'],['Local','No, it is about a five-minute walk.','不远，步行大约五分钟。']],quiz:[['Where is Sunny going?',['A station','A hotel','A cafe'],0],['How long is the walk?',['Fifteen minutes','Five minutes','An hour'],1]],prompts:[['Can I help you?','需要帮助吗？','Where is the nearest subway station?'],['Where would you like to go?','你想去哪里？','I would like to go to the city center.'],['Do you have a map?','你有地图吗？','Yes. Could you show me on the map?'],['Would you like to walk?','你想步行吗？','Is it far from here?'],['Do you understand the directions?','你明白怎么走了吗？','Go straight and turn left. Thank you!']]},
{id:5,title:'把 Bug 讲清楚',en:'Let’s reproduce it',category:'工作',topic:'与开发同事沟通问题',seed:[['bug','程序缺陷','I found a bug in the API.'],['reproduce','复现','I can reproduce the issue.'],['steps','步骤','Here are the steps.'],['expected','预期的','This is the expected result.'],['actual','实际的','The actual result is different.'],['log','日志','Please check the log.'],['request','请求','The request failed.'],['response','响应','The response is empty.'],['resolve','解决','We need to resolve this issue.'],['confirm','确认','Let me confirm the result.']],lines:[['Sunny','I found a bug in the login API.','我在登录接口发现了一个 Bug。'],['Dev','Can you reproduce it?','你能复现吗？'],['Sunny','Yes. Send a request with an empty password.','可以，发送一个密码为空的请求。'],['Dev','What is the actual result?','实际结果是什么？'],['Sunny','The server returns an error. I will share the logs.','服务器返回错误。我会分享日志。']],quiz:[['Where is the bug?',['Login API','Shopping page','Email'],0],['What will Sunny share?',['Tickets','Logs','A map'],1]],prompts:[['What issue did you find?','你发现了什么问题？','I found a bug in the login API.'],['Can you reproduce it?','你能复现吗？','Yes. I can reproduce it every time.'],['What are the steps?','步骤是什么？','Send a request with an empty password.'],['What is the actual result?','实际结果是什么？','The server returns an error.'],['Could you send me more details?','能给我更多细节吗？','Of course. I will share the steps and logs.']]},
{id:6,title:'入住酒店与周复习',en:'A room for tonight',category:'出国',topic:'在酒店前台办理入住',seed:[['reservation','预订','I have a reservation.'],['passport','护照','Here is my passport.'],['check in','办理入住','I would like to check in.'],['check out','退房','What time is check-out?'],['breakfast','早餐','Is breakfast included?'],['included','包含的','Breakfast is included.'],['room','房间','Could I have a quiet room?'],['key','钥匙','Here is your room key.'],['floor','楼层','Your room is on the third floor.'],['luggage','行李','Can I leave my luggage here?']],lines:[['Sunny','Hello, I have a reservation under Sunny.','你好，我用 Sunny 的名字预订了房间。'],['Reception','May I see your passport, please?','可以看一下你的护照吗？'],['Sunny','Of course. Is breakfast included?','当然。包含早餐吗？'],['Reception','Yes. Breakfast is from seven to ten.','是的，早餐时间是七点到十点。']],quiz:[['What does Sunny have?',['A reservation','A train ticket','A new job'],0],['When does breakfast end?',['At seven','At ten','At twelve'],1]],prompts:[['Hello, how can I help you?','你好，需要什么帮助？','I have a reservation under Sunny.'],['May I see your passport?','可以看一下你的护照吗？','Of course. Here it is.'],['Do you have any questions?','还有什么问题吗？','Is breakfast included?'],['When would you like to check out?','你想什么时候退房？','What time is check-out?'],['Is there anything else you need?','还需要其他帮助吗？','Can I leave my luggage here after check-out?']]},
{id:7,title:'聊聊你的周末',en:'How was your week?',category:'日常',topic:'轻量复习与自由表达',seed:[['weekend','周末','How was your weekend?'],['relax','放松','I like to relax at home.'],['visit','拜访','I visited a friend.'],['enjoy','享受','I enjoy walking.'],['usually','通常','I usually cook at home.'],['sometimes','有时','I sometimes watch movies.'],['plan','计划','What is your plan?'],['learn','学习','I learned ten new words.'],['practice','练习','I practice speaking every day.'],['confident','自信的','I feel more confident now.']],lines:[['Tom','How was your weekend?','你周末过得怎么样？'],['Sunny','It was great. I visited a friend and cooked dinner.','很好，我拜访了朋友，还做了晚饭。'],['Tom','Did you practice English too?','你也练习英语了吗？'],['Sunny','Yes. I practiced speaking for fifteen minutes.','是的，我练了十五分钟口语。']],quiz:[['Who did Sunny visit?',['A teacher','A friend','A client'],1],['How long did Sunny practice?',['Five minutes','Fifty minutes','Fifteen minutes'],2]],prompts:[['How was your weekend?','你周末过得怎么样？','It was great. I visited a friend.'],['What do you usually do to relax?','你通常如何放松？','I usually take a walk or watch a movie.'],['What did you learn this week?','你这周学到了什么？','I learned how to introduce myself and order coffee.'],['What was difficult for you?','你觉得什么比较难？','Listening was difficult, but I kept practicing.'],['What will you practice next week?','你下周想练习什么？','I will practice describing my work in English.']]}
];
