lessons[0].words[6]=['workflow','/ˈwɜːrkfloʊ/','工作流、流程','I test approval workflows in our internal system.','我测试内部系统中的审批流程。'];
lessons[0].lines[3]=['Sunny','I’m a QA engineer. I mainly test HR systems and approval workflows.','我是一名 QA 工程师，主要测试 HR 系统和审批流程。'];
