Object.assign(lessons[2],{title:'请假申请与审批状态',en:'A leave request',topic:'测试请假单的提交和审批',seed:[['leave request','请假申请','I submitted a leave request.'],['approval','审批','The request is waiting for approval.'],['approver','审批人','Who is the approver?'],['submit','提交','Please submit the form.'],['pending','待处理的','The status is pending.'],['approve','批准','The manager can approve the request.'],['reject','拒绝','The manager rejected the request.'],['return','退回','The form was returned to the applicant.'],['applicant','申请人','The applicant can edit the form.'],['status','状态','The status did not change.']],lines:[['Colleague','What are you testing today?','你今天在测试什么？'],['Sunny','I am testing the leave approval workflow.','我在测试请假审批流程。'],['Colleague','What happens after the employee submits the form?','员工提交表单后会发生什么？'],['Sunny','The status changes to pending. The manager receives a notification.','状态变为待处理，经理收到通知。'],['Colleague','Did you find any issues?','发现问题了吗？'],['Sunny','Yes. The approver did not receive the notification.','是的，审批人没有收到通知。']],quiz:[['What is Sunny testing?',['A payment API','A leave approval workflow','A public website'],1],['What is the issue?',['Missing notification','Wrong password','Slow internet'],0]],prompts:[['What are you testing today?','今天测试什么？','I am testing the leave approval workflow.'],['Who can submit a leave request?','谁可以提交请假申请？','An employee can submit a leave request.'],['What is the current status?','当前状态是什么？','The status is pending.'],['What happens after approval?','批准之后会怎样？','The status changes to approved.'],['What issue did you find?','发现了什么问题？','The approver did not receive the notification.']]});
Object.assign(lessons[4],{title:'报销单、权限与流程缺陷',en:'Testing an approval form',topic:'向同事描述内部审批单缺陷',seed:[['reimbursement','报销','I am testing the reimbursement form.'],['permission','权限','This user does not have permission.'],['attachment','附件','The attachment is missing.'],['required field','必填项','This is a required field.'],['amount','金额','The amount is incorrect.'],['resubmit','重新提交','The applicant can resubmit the form.'],['withdraw','撤回','The employee can withdraw the request.'],['approval step','审批节点','The form skipped an approval step.'],['notification','通知','The approver did not receive a notification.'],['reproduce','复现','I can reproduce the issue.']],lines:[['Sunny','I found an issue in the reimbursement workflow.','我在报销流程中发现一个问题。'],['Dev','How can I reproduce it?','怎么复现？'],['Sunny','Log in as an employee and submit a form without an attachment.','用员工账号登录，不添加附件直接提交表单。'],['Dev','What should happen?','预期会怎样？'],['Sunny','The system should show an error. But the form was submitted successfully.','系统应该提示错误，但表单提交成功了。']],quiz:[['Which workflow has an issue?',['Leave','Reimbursement','Hotel booking'],1],['What is missing?',['An attachment','A password','A room key'],0]],prompts:[['Where did you find the issue?','你在哪里发现了问题？','I found an issue in the reimbursement workflow.'],['Which account did you use?','你使用什么账号？','I logged in as an employee.'],['How can I reproduce it?','怎么复现？','Submit the form without an attachment.'],['What is the expected result?','预期结果是什么？','The system should show an error because the attachment is required.'],['What is the actual result?','实际结果是什么？','The form was submitted successfully.']]});
lessons.forEach(l=>{if(!l.words)l.words=l.seed.map(w=>[w[0],'',w[1],w[2],'']);if(!l.phrases)l.phrases=l.prompts.map(p=>p[2]);});
